/bin/bash -lc "python3 - <<'PY'
import json,os,urllib.request
base='/workspace/mcp-eval'
s=json.load(open(base+'/docs/openapi.json'))
for p in ['/organizations','/models','/organizations/{organizationId}/spend-budget','/projects/{projectId}/eval-runs']:
 print(p,json.dumps(s['paths'][p])[:24000])
for name,path in [('organizations','/organizations'),('models','/models'),('servers','/projects/project_fixture/servers')]:
 req=urllib.request.Request(os.environ['MCPJAM_API_URL']+path,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY']})
 try:
  r=urllib.request.urlopen(req); data=r.read().decode()
 except urllib.error.HTTPError as e:data=e.read().decode()
 open(base+'/results/'+name+'.json','w').write(data);print(name,data)
PY"

